from collections import defaultdict

def candidate(grid):
    H,W=len(grid),len(grid[0]); bg=max(set(v for row in grid for v in row),key=lambda x:sum(row.count(x) for row in grid))
    seen=set(); comps=[]
    for r in range(H):
      for c in range(W):
        if grid[r][c]==bg or (r,c) in seen: continue
        col=grid[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
        while st:
          a,b=st.pop(); cells.append((a,b))
          for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
            if 0<=x<H and 0<=y<W and (x,y) not in seen and grid[x][y]==col:
              seen.add((x,y));st.append((x,y))
        r0=min(a for a,b in cells); r1=max(a for a,b in cells); c0=min(b for a,b in cells); c1=max(b for a,b in cells)
        local={(a-r0,b-c0) for a,b in cells}; h=r1-r0+1;w=c1-c0+1
        edgeL=({(0,j) for j in range(w)}|{(i,0) for i in range(h)})
        corners=[]
        for cr,cc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
          el=({(cr,j) for j in range(c0,c1+1)}|{(i,cc) for i in range(r0,r1+1)})
          if set(cells)==el:corners.append((cr,cc))
        variants=[]
        for flip in (1,-1):
          for rot in range(4):
            pts=[]
            for x,y in local:
              x*=flip
              for _ in range(rot): x,y=y,-x
              pts.append((x,y))
            mnx=min(x for x,y in pts);mny=min(y for x,y in pts)
            variants.append(tuple(sorted((x-mnx,y-mny) for x,y in pts)))
        comps.append(dict(color=col,cells=cells,shape=min(variants),corners=corners,center=(sum(a for a,b in cells)/len(cells),sum(b for a,b in cells)/len(cells))))
    refs=[o for o in comps if o['corners'] and any(r in (0,H-1) or c in (0,W-1) for r,c in o['cells'])]
    ref=max(refs,key=lambda o:len(o['cells']))
    elbow=ref['corners'][0]
    groups=defaultdict(list)
    for o in comps:
      if o is not ref:groups[o['shape']].append(o)
    rep=[g for g in groups.values() if len(g)>=2]
    size=max(len(g[0]['cells']) for g in rep)
    cand=[o for g in rep if len(g[0]['cells'])==size for o in g]
    target=max(cand,key=lambda o:(o['center'][0]-elbow[0])**2+(o['center'][1]-elbow[1])**2)
    out=[row[:] for row in grid]
    for r,c in target['cells']:out[r][c]=ref['color']
    return out, (ref['color'],elbow,[(len(g[0]['cells']),len(g)) for g in rep],target['color'],target['cells'])
